import React, { useState } from 'react';
import { Card, CardContent } from '../ui/card';
import { Avatar, AvatarFallback } from '../ui/avatar';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Mail, Phone, MapPin, FileText, Users } from 'lucide-react';
import { AssignConsultantModal } from '../modals/AssignConsultantModal';
import { useAuth } from '../../contexts/AuthContext';

export const ClientCard = ({ client, onUpdate }) => {
  const { user } = useAuth();
  const [showAssignModal, setShowAssignModal] = useState(false);
  
  const canManageTeam = user?.role === 'admin' || user?.role === 'super_admin';

  return (
    <>
      <Card>
        <CardContent className="p-6">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center space-x-4">
              <Avatar className="h-12 w-12">
                <AvatarFallback className="bg-green-100 text-green-700 text-lg font-bold">
                  {client.company_name.substring(0, 2).toUpperCase()}
                </AvatarFallback>
              </Avatar>
              <div>
                <h3 className="text-lg font-semibold text-gray-900">
                  {client.company_name}
                </h3>
                <p className="text-sm text-gray-600">{client.contact_person}</p>
                <p className="text-sm text-gray-500 capitalize">{client.industry}</p>
              </div>
            </div>
            
            <div className="flex flex-col items-end gap-2">
              <Badge className={client.status === 'active' 
                ? 'bg-green-100 text-green-800' 
                : 'bg-gray-100 text-gray-800'
              }>
                {client.status === 'active' ? 'Activo' : 'Inactivo'}
              </Badge>
              
              <div className="flex gap-2">
                {canManageTeam && (
                  <Button 
                    variant="outline" 
                    size="sm" 
                    onClick={() => setShowAssignModal(true)}
                    className="hover:bg-green-50 hover:text-green-700 hover:border-green-300"
                  >
                    <Users className="w-4 h-4 mr-2" />
                    Equipo
                  </Button>
                )}
                <Button variant="outline" size="sm">
                  <FileText className="w-4 h-4 mr-2" />
                  Proyectos
                </Button>
              </div>
            </div>
          </div>
          
          <div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm text-gray-600">
            <div>
              <p className="flex items-center">
                <Mail className="w-4 h-4 mr-2 text-gray-400" />
                {client.email}
              </p>
              <p className="flex items-center mt-1">
                <Phone className="w-4 h-4 mr-2 text-gray-400" />
                {client.phone}
              </p>
            </div>
            <div>
              <p className="flex items-center">
                <MapPin className="w-4 h-4 mr-2 text-gray-400" />
                {client.address}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Modal de Asignación de Consultores */}
      <AssignConsultantModal
        isOpen={showAssignModal}
        onClose={() => setShowAssignModal(false)}
        client={client}
        onSuccess={onUpdate}
      />
    </>
  );
};
